head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — selectList 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.selectList(true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL57000.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name sbx_periodTp_onselchange
 * @description 조회기간 구분 선택 변경 — 선택 기간의 시작일·종료일·연도·구분코드를 조회조건에 반영한다.
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_periodTp_onselchange = function (info) {
    try {
        let seletedIndex = sbx_periodTp.getSelectedIndex();
        ibx_strtDd.setValue(dlt_PeriodRes.getCellData(seletedIndex, "strtDd"));
        ibx_endtDd.setValue(dlt_PeriodRes.getCellData(seletedIndex, "endDd"));

        dma_SearchReq.set("yyyy", dlt_PeriodRes.getCellData(seletedIndex, "yyyy"))
        dma_SearchReq.set("valuTpCd", dlt_PeriodRes.getCellData(seletedIndex, "valuTmTpCd"))
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL57000.sbx_periodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 버튼 클릭 — 상장주선인 평가정보를 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_search_onclick = function (e) {
    try {
        scwin.selectList();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL57000.btn_search_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name selectList
 * @description 상장주선인 평가정보 목록을 조회한다.
 * @param {Boolean} isFirst 최초 조회 여부
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectList = async function (isFirst) {

    const sbmOptions = {
        id : "sbm_repleadcomEvalinfo",
        action : "/api/listing/listinvstg/repleadcom-evalinfo",
        method : "get",
        ref : "dma_SearchReq",
        target : "dlt_PeriodRes=body.periodList,dlt_corpStkChgStatDtoRes=body.corpStkChgStatDto,dma_period=body.period,dlt_profitChgStatDtoRes=body.profitChgStatDto,dlt_secMktCtrbStatDtoRes=body.secMktCtrbStatDto,dlt_corpDdStatDtoRes=body.corpDdStatDto",
        gridview : "grd_companyState",
        isProcessMsg : false
    };
    let res = await $c.sbm.executeDynamic(sbmOptions);

    if (res.responseJSON.success === true) {
        if(isFirst) {
            ibx_strtDd.setValue(res.responseJSON.body.periodList[0].strtDd);
            ibx_endtDd.setValue(res.responseJSON.body.periodList[0].endDd);

        }

    const yyyy =  dma_period.get("yyyy");
    const valuTpCd = dma_period.get("valuTpCd");

    let labelText ="";

        if(valuTpCd === "1") { // 상반기
        labelText = String(yyyy) + " 상반기";
        } else {   // 하반기
        labelText = String(yyyy) + " 하반기";
        }
        sbx_periodTp.setText(labelText);
    }

};
